WITH joined AS (SELECT src.id, src.customer_id, src.device, src.browser, src.started_at, p.country AS customer_country, p.age FROM sessions src LEFT JOIN customers p ON src.customer_id = p.id) SELECT s.id, s.customer_id, s.device, s.age, CASE WHEN device RLIKE '^(desktop|mobile)$' THEN 'EXTENDED' WHEN device RLIKE '^(tablet)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS device_zone, (SELECT SUM(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_amount FROM joined s ORDER BY id DESC NULLS LAST LIMIT 5;
